  <a href="/">Home</a> |
  <a href="/about">About</a> |
  <a href="/help">Help</a> |
  <a href="/status">Status</a> |
  <a href="/api">API</a> |
  <a href="/dashboard">Dashboard</a>
</nav>
${body}
</body>
</html>`;
}

