from pathlib import Path

p = Path("/app/app.js")
s = p.read_text()

# Replace the /debug route mapping
old_debug = """// flag_2: env-dump diagnostics exposed at exactly one un-advertised path,
// GET /debug/env. It is mapped onto the debug router's /diagnostics handler so
// the patch that disables that handler (routes/debug.js) also closes this
// surface. Only /debug/env is reachable; any other /debug/* path returns 404.
app.use('/debug', (req, res, next) => {
  if (req.url === '/env' || req.url === '/env/') { req.url = '/diagnostics'; return next(); }
  return res.status(404).json({ error: 'Not found' });
}, require('./routes/debug'));"""

new_debug = """// PATCHED (VULN-02): /debug/env is now removed entirely. No unauthenticated
// environment dump endpoint is accessible.
app.use('/debug', (req, res) => {
  return res.status(404).json({ error: 'Not found' });
});"""

if old_debug in s:
    s = s.replace(old_debug, new_debug)
    p.write_text(s)
    print("app.js patched: debug endpoint removed")
else:
    print("WARNING: exact text not matched, trying simpler approach")
    # Simpler: just remove all /debug routes by commenting out
    lines = s.split('\n')
