from pathlib import Path

# Fix 4: IDOR in reports.js
p = Path("/app/routes/reports.js")
s = p.read_text()

old_idor = """// flag_1: IDOR/BOLA — no per-object owner check on /:id so any
// authenticated user can read any report by enumerating its numeric id.
router.get('/:id', requireAuth, (req, res) => {
  const row = db
    .prepare('SELECT id, title, body, owner, escalation_ref FROM reports WHERE id = ?')
    .get(req.params.id);
  if (!row) return res.status(404).json({ error: 'Report not found' });
  res.json(row);
});"""

new_idor = """// PATCHED (VULN-01): IDOR fixed — owner check added.
// Only the report owner or admin can read a report by id.
router.get('/:id', requireAuth, (req, res) => {
  const row = db
    .prepare('SELECT id, title, body, owner, escalation_ref FROM reports WHERE id = ?')
    .get(req.params.id);
  if (!row) return res.status(404).json({ error: 'Report not found' });
  // Verify ownership: only admin or the report owner may read
  if (req.user.role !== 'admin' && req.user.username !== row.owner) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json(row);
});"""

if old_idor in s:
    s = s.replace(old_idor, new_idor)
    p.write_text(s)
    print("reports.js patched: IDOR fixed")
else:
    print("WARNING: IDOR text not matched")

# Fix 5: Reused keystream in exports.js
p2 = Path("/app/routes/exports.js")
s2 = p2.read_text()

old_xor = """// flag_3: XOR "encryption" using a fixed keystream (many-time pad).
// Every item encrypted with the same keystream reveals xor(c1,c2) = xor(p1,p2).
// Known plaintext (a task description) + its ciphertext recovers the keystream.
const KEYSTREAM = Buffer.from(
  'f4e8c3b72a9d10e547fc6a8b31c295e0d7e1f3a6b8c2d5e7094f1a3b6c8d2e4f' +
  'a7b3c8d2e1f5093a4b7c6d8e2f1094a5b3c7d1e8f20394b5a7c8d1e3f60495a2b' +
  'c7d8e1f3094a5b6c7d8e2f10a3b495c6d7e8f10293a4b5c7d8e9f6f6',
  'hex'
);"""

new_xor = """// PATCHED (VULN-03): fixed keystream replaced with per-request random keystream.
// Each encryption now uses a unique random keystream generated via crypto.randomBytes.
const crypto = require('crypto');

function getKeystream() {
  return crypto.randomBytes(256);
}"""

# Also fix the v1_xor to use getKeystream
old_xor_enc = """function v1_xor(plaintext) {
  assert(plaintext.length > 0, 'plaintext required');

  // Pad short payloads with spaces
  let pt = Buffer.from(plaintext, 'utf8');
  if (pt.length < KEYSTREAM.length) {
    pt = Buffer.concat([pt, Buffer.alloc(KEYSTREAM.length - pt.length, 0x20)]);
  }

  const ct = Buffer.alloc(pt.length);
  for (let i = 0; i < pt.length; i++) {
    ct[i] = pt[i] ^ KEYSTREAM[i % KEYSTREAM.length];
  }
  return ct;
}"""

new_xor_enc = """function v1_xor(plaintext) {
  assert(plaintext.length > 0, 'plaintext required');

  // Pad short payloads with spaces
  let pt = Buffer.from(plaintext, 'utf8');
  if (pt.length < 256) {
    pt = Buffer.concat([pt, Buffer.alloc(256 - pt.length, 0x20)]);
  }

  // Use a per-request random keystream (PATCHED VULN-03)
  const ks = getKeystream();
  const ct = Buffer.alloc(pt.length);
  for (let i = 0; i < pt.length; i++) {
    ct[i] = pt[i] ^ ks[i % ks.length];
  }
  return ct;
}"""

if old_xor in s2:
    s2 = s2.replace(old_xor, new_xor)
    print("exports.js: replaced KEYSTREAM constant")
else:
    print("WARNING: KEYSTREAM text not matched")

if old_xor_enc in s2:
    s2 = s2.replace(old_xor_enc, new_xor_enc)
    print("exports.js: replaced v1_xor function")
else:
    print("WARNING: v1_xor text not matched")

p2.write_text(s2)
print("exports.js patched: per-request random keystream")

# Fix 6: Remove password_hash from user API
p3 = Path("/app/routes/users.js")
s3 = p3.read_text()

# Replace SELECT * with explicit columns (no password_hash)
old_user_me = "SELECT * FROM users WHERE id = ?"
old_user_lookup = "SELECT * FROM users WHERE username = ?"

if old_user_me in s3:
    s3 = s3.replace(old_user_me, "SELECT id, username, role FROM users WHERE id = ?")
if old_user_lookup in s3:
    s3 = s3.replace(old_user_lookup, "SELECT id, username, role FROM users WHERE username = ?")

p3.write_text(s3)
print("users.js patched: password_hash removed from API responses")

# Fix 7: Remove demo credentials from /help page
p4 = Path("/app/app.js")
s4 = p4.read_text()

old_help = "<!-- QA demo account for smoke tests, remove before GA: manager / manager456 -->"
if old_help in s4:
    s4 = s4.replace(old_help, "<!-- Demo accounts are not published in production. -->")
    p4.write_text(s4)
    print("app.js patched: demo credentials removed from /help")
else:
    print("WARNING: demo creds comment not found")

print("\nAll patches applied. Summary:")
print("- reports.js: IDOR fixed (owner check)")
print("- exports.js: random keystream per request")
print("- users.js: no more password_hash in API")
print("- app.js: demo creds removed")

